test('tDistTwoTailedP: 已知临界值', () => {
  // df=1 即 Cauchy 分布，t=1 时双侧 p = 0.5
  assert.ok(Math.abs(tDistTwoTailedP(1, 1) - 0.5) < 1e-9);
